import importlib,sys,json,time,subprocess,os
from pathlib import Path
if len(sys.argv)>1:
 import polars as pl
 from ibex_polars import IbexEngine
 sys.path.insert(0,'/home/brj/code/polars-benchmark')
 root=Path('/home/brj/code/polars-benchmark/data/tables/scale-10.0')
 q=importlib.import_module('queries.polars.q18').q(**{p.stem:pl.scan_parquet(p) for p in root.glob('*.parquet')})
 route=sys.argv[1];engine=IbexEngine().prepare(q) if route=='polars_ibex' else route
 start=time.perf_counter_ns();r=q.collect(engine=engine);elapsed=(time.perf_counter_ns()-start)/1e6
 print(json.dumps({'ms':elapsed,'data':r.to_dict(as_series=False),'dtypes':list(map(str,r.dtypes))},default=str))
else:
 out={}
 for threads,affinity in [(1,'2'),(8,'0,2,4,6,8,10,12,14')]:
  entries={};reference=None
  for route in ['streaming','in-memory','polars_ibex']:
   env=os.environ.copy();env.update(IBEX_CORES=str(threads),POLARS_MAX_THREADS=str(threads),OPENBLAS_NUM_THREADS='1')
   result=json.loads(subprocess.check_output(['taskset','-c',affinity,sys.executable,__file__,route],env=env,text=True))
   if reference is None: reference=(result['data'],result['dtypes'])
   else: assert (result['data'],result['dtypes'])==reference
   entries[route]={'ms':result['ms'],'rows':len(next(iter(result['data'].values()))),'exact_result_and_dtypes_match':True}
  out[str(threads)]=entries
 report={'method':'fresh process per executor and budget; one prepared collection each; warm file cache; no previous query in worker', 'query':'q18', 'results':out}
 Path('/tmp/pdsh-q18-fresh.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(out))
